// 1. Validate incoming Clinova request payload
const raw = $input.first().json;
const body = raw.body || raw;

if (!body || typeof body !== 'object') {
  return [{ json: { isValid: false, error: 'Empty or invalid JSON body', caseId: null } }];
}

const caseId = body.caseId;
const chiefComplaint = body.chiefComplaint;

if (!caseId || typeof caseId !== 'string' || caseId.trim() === '') {
  return [{ json: { isValid: false, error: 'Missing or invalid required field: caseId', caseId: null } }];
}

if (!chiefComplaint || typeof chiefComplaint !== 'string' || chiefComplaint.trim() === '') {
  return [{ json: { isValid: false, error: 'Missing or invalid required field: chiefComplaint', caseId: caseId } }];
}

// Format and sanitize prompt context for LLM / AI Agent
return [{
  json: {
    isValid: true,
    caseId: caseId.trim(),
    caseReference: body.caseReference || caseId,
    patientName: body.patientName || 'Patient',
    patientId: body.patientId || '',
    submissionTimestamp: body.submissionTimestamp || new Date().toISOString(),
    chiefComplaint: chiefComplaint.trim(),
    duration: body.duration || 'Not specified',
    severity: body.severity || 'Not specified',
    associatedSymptoms: Array.isArray(body.associatedSymptoms) ? body.associatedSymptoms : [],
    otherAssociatedSymptom: body.otherAssociatedSymptom || 'None',
    triggersAndRelief: body.triggersAndRelief || 'None reported',
    previousOccurrences: body.previousOccurrences || 'Not specified',
    previousOccurrenceDetails: body.previousOccurrenceDetails || 'None',
    existingConditions: Array.isArray(body.existingConditions) ? body.existingConditions : [],
    allergies: Array.isArray(body.allergies) ? body.allergies : [],
    allergyDetails: body.allergyDetails || 'None',
    takesMedications: body.takesMedications || 'Not specified',
    medicationDetails: body.medicationDetails || 'None',
    medicalFamilyHistory: body.medicalFamilyHistory || 'None reported'
  }
}];

parameters.text:
=You are Clinova's AI Clinical Decision Support Specialist. Your role is to formulate a structured clinical briefing for the attending physician based STRICTLY on the patient intake responses below.

CRITICAL HEALTHCARE SAFETY CONSTRAINTS:
1. NEVER invent, hallucinate, or assume symptoms, physical exam findings, or diagnostic test values.
2. NEVER output definitive diagnoses or prescribe medications.
3. Include in 'relevantPositiveFindings' ONLY symptoms explicitly endorsed by the patient.
4. Include in 'relevantNegativeFindings' ONLY symptoms explicitly denied by the patient (e.g. if previousOccurrences is 'No', or associatedSymptoms is 'None of these', or allergies is 'No known allergies'). NEVER invent absent symptoms.
5. Provide 2-4 insightful clarification questions for the physician in 'missingOrUnclearInformation'.

PATIENT INTAKE CASE:
- Case ID: {{ $json.caseId }}
- Patient Name / ID: {{ $json.patientName }} ({{ $json.patientId }})
- Chief Complaint: {{ $json.chiefComplaint }}
- Duration & Progression: {{ $json.duration }}
- Severity: {{ $json.severity }}
- Associated Symptoms: {{ $json.associatedSymptoms.join(', ') }} (Other: {{ $json.otherAssociatedSymptom }})
- Triggers & Relieving Factors: {{ $json.triggersAndRelief }}
- Previous Similar Episodes: {{ $json.previousOccurrences }} (Details: {{ $json.previousOccurrenceDetails }})
- Chronic Conditions: {{ $json.existingConditions.join(', ') }}
- Allergies: {{ $json.allergies.join(', ') }} (Details: {{ $json.allergyDetails }})
- Active Medications: {{ $json.takesMedications }} (Details: {{ $json.medicationDetails }})
- Medical & Family History: {{ $json.medicalFamilyHistory }}

Synthesize this into the structured JSON schema provided.

parameters.jsCode:
// 3. Safety Enforcement & Schema Normalization
const raw = $input.first().json;
let output = raw.output || raw.response || raw;

// Parse stringified JSON if needed
if (typeof output === 'string') {
  try {
    output = JSON.parse(output);
  } catch (e) {
    // If parsing fails, wrap
    output = { summaryText: output };
  }
}

const caseId = $('Validate Request Payload').first().json.caseId;
const chiefComplaint = $('Validate Request Payload').first().json.chiefComplaint;

return [{
  json: {
    caseId: output.caseId || caseId,
    generationStatus: 'ready',
    generatedAt: new Date().toISOString(),
    summaryText: output.summaryText || 'Clinical summary synthesized successfully.',
    chiefComplaint: output.chiefComplaint || chiefComplaint,
    symptomTimelineAndSeverity: output.symptomTimelineAndSeverity || 'Timeline recorded from patient intake.',
    relevantPositiveFindings: Array.isArray(output.relevantPositiveFindings) ? output.relevantPositiveFindings : [chiefComplaint],
    relevantNegativeFindings: Array.isArray(output.relevantNegativeFindings) ? output.relevantNegativeFindings : ['No chronic conditions reported'],
    medicalHistoryAndMedications: output.medicalHistoryAndMedications || 'Medical history documented.',
    missingOrUnclearInformation: Array.isArray(output.missingOrUnclearInformation) ? output.missingOrUnclearInformation : ['Clarify onset progression with patient'],
    disclaimer: 'AI-generated summary — requires physician review. Not a diagnosis or prescription.'
  }
}];
